app.use((req, res, next) =&gt; {

const token = req.headers.authorization?.split(' ')[1];

if (!token) return res.status(401).send('토큰 없음');

try {

const decoded = jwt.verify(token, process.env.JWT_SECRET);

req.user = decoded;

next();

} catch (err) {

return res.status(401).send('유효하지 않은 토큰');

}

});

